def dense_cr(P, per=12):
 P=np.asarray(P,float); out=[]
 for i in range(len(P)-1):
  p0=P[max(i-1,0)];p1=P[i];p2=P[i+1];p3=P[min(i+2,len(P)-1)]
  for t in np.linspace(0,1,per,endpoint=False):
   out.append(.5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t))
 out.append(P[-1]);return np.array(out)
def resample(P,step=9):
 d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(P,axis=0),axis=1))];ss=np.arange(0,d[-1],step);ss=np.r_[ss,d[-1]]
 return np.column_stack([np.interp(ss,d,P[:,k]) for k in range(2)]),d[-1]
